"const xlsx = require('xlsx');
const fs = require('fs');
const workbook = xlsx.readFile('homologacion.xlsx');
const sheet = workbook.Sheets[workbook.SheetNames[0]];
const data = xlsx.utils.sheet_to_json(sheet);

let tsContent = 'export const MAPPING_ESTABLECIMIENTOS: Record<string, { sector: string, estabBase: string }> = {\\n';

data.forEach(row => {
  const est = String(row['ESTABLECIMIENTO'] || '').trim();
  const base = String(row['ESTAB_BASE'] || '').trim();
  const sector = String(row['SECTOR'] || '').trim();

  if (est) {
    tsContent += `  "${est.replace(/"/g, '\\"')}": { sector: "${sector.replace(/"/g, '\\"')}", estabBase: "${base.replace(/"/g, '\\"')}" },\n`;
  }
});

tsContent += '};\n';

fs.writeFileSync('lib/mappingEstablecimientos.ts', tsContent);
console.log('Diccionario creado con éxito.');"

"const { PrismaClient } = require('@prisma/client');
const p = new PrismaClient();
async function main() {
  await p.resumenSiniestro.deleteMany();
  await p.siniestro.deleteMany();
}
main().finally(() => p.$disconnect());"

